using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class JobAlertsPage:UserControl{DataGridView grid;TextBox keyword,city;ComboBox frequency;public JobAlertsPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;Padding=new Padding(18);var form=new FlowLayoutPanel{Dock=DockStyle.Top,Height=74,FlowDirection=L.Fa?FlowDirection.RightToLeft:FlowDirection.LeftToRight,WrapContents=false};keyword=Ui.Text();keyword.Width=220;city=Ui.Text();city.Width=160;frequency=new ComboBox{Width=140,DropDownStyle=ComboBoxStyle.DropDownList};frequency.Items.AddRange(new object[]{"Daily","Weekly"});frequency.SelectedIndex=0;var add=Ui.Button(L.Fa?"ایجاد هشدار":"Create alert");var del=Ui.Button(L.Fa?"حذف":"Delete",false);add.Click+=delegate{Add();};del.Click+=delegate{Delete();};form.Controls.Add(Ui.Label(L.Fa?"کلیدواژه":"Keyword"));form.Controls.Add(keyword);form.Controls.Add(Ui.Label(L.Fa?"شهر":"City"));form.Controls.Add(city);form.Controls.Add(frequency);form.Controls.Add(add);form.Controls.Add(del);grid=Ui.Grid();Controls.Add(grid);Controls.Add(form);LoadData();}void LoadData(){grid.DataSource=Database.Query("SELECT Id,Keyword,City,Frequency,IsActive,CreatedAt FROM JobAlerts WHERE UserId=@u ORDER BY CreatedAt DESC",new SqlParameter("@u",AppSession.UserId));}void Add(){if(string.IsNullOrWhiteSpace(keyword.Text)){MessageBox.Show(L.Fa?"کلیدواژه را وارد کنید.":"Enter a keyword.");return;}Database.Exec("INSERT JobAlerts(UserId,Keyword,City,Frequency) VALUES(@u,@k,@c,@f)",new SqlParameter("@u",AppSession.UserId),new SqlParameter("@k",keyword.Text.Trim()),new SqlParameter("@c",city.Text.Trim()),new SqlParameter("@f",frequency.Text));Database.Audit("CreateJobAlert","JobAlert",keyword.Text.Trim());keyword.Clear();city.Clear();LoadData();}void Delete(){if(grid.CurrentRow==null)return;int id=Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value);Database.Exec("DELETE JobAlerts WHERE Id=@i AND UserId=@u",new SqlParameter("@i",id),new SqlParameter("@u",AppSession.UserId));LoadData();}}}
